        "question": "Turnusol boyası asidik ortamda kırmızı, bazik ortamda mavi renk alan yaygın bir indikatördür.\nAşağıdaki çözeltilerden hangisine kırmızı turnusol kâğıdı daldırıldığında **rengi maviye döner?**",
