        "id": "KIM-TYT-K08-T03-S07",
        "question": "Oda koşullarındaki bir sulu çözeltide, hidrojen iyonu ($H^+$) derişimi, hidroksit iyonu ($OH^-$) derişiminden daha **fazladır**.\nBuna göre bu çözelti ile ilgili;\nI. Asidik özellik gösterir.\nII. pH değeri 7'den küçüktür.\nIII. Mavi turnusolu kırmızıya çevirir.\nyargılarından hangileri doğrudur?",
