        "question": "Mide asidi (yaklaşık pH 1.5 - 2) yiyeceklerin sindirimine yardımcı olur ancak bazen aşırı salgılanması mide yanmasına (ülser, reflü vb.) neden olur.\nMide yanmasını hafifletmek için alınan \"Antiasit\" ilaçlarının etken maddesi genellikle aşağıdakilerden hangisidir?",
