        "question": "Ağızda kalan yemek artıkları, bakteriler tarafından parçalanarak organik asitlere dönüşür. Bu asitler diş minesindeki kalsiyum bileşiklerini aşındırarak diş çürüklerine neden olur.\nBuna göre;\nI. Diş macunları genellikle bazik karakterde üretilir.\nII. Yemekten sonra asidik içecekler (kola vb.) içmek diş minesinin çürümesini hızlandırır.\nIII. Ağız pH'ının sürekli 7'nin üzerinde (bazik) kalması çürümeyi hızlandıran temel faktördür.\nyargılarından hangileri doğrudur?",
