        "question": "Ahmet usta, tıkanan lavaboyu açmak için marketten \"Lavabo Açıcı\" (Sud kostik, $NaOH$ granülleri) almış ve lavaboya döktükten sonra üzerine kaynar su eklemiştir.\nBu işlem sırasında lavabodan şiddetli bir fokurdama, buhar ve kötü koku çıkmıştır.\nBu durumla ilgili;\nI. $NaOH$'ın suda çözünmesi aşırı derecede ekzotermiktir (ısı verir), bu yüzden su fokurdar ve sıçrar.\nII. Lavabodaki saç, yağ ve organik atıklar kuvvetli baz olan $NaOH$ tarafından parçalanıp (sabunlaşma/hidroliz) sıvılaşır.\nIII. $NaOH$ asidik bir madde olduğu için yağları asitle yakarak yok etmiştir.\nyargılarından hangileri doğrudur?",
