        "solution": "Sud kostik (NaOH) katısı suda çözündüğünde çok yüksek miktarda ısı açığa çıkarır (Ekzotermiktir), kaynar suyla birleştiğinde fokurdar (I doğru). Bu yüksek ısı ve kuvvetli bazik ortam, organik atıkları (saç, yağ) parçalayıp suda çözünür hâle getirir (II doğru). Ancak NaOH asit DEĞİLDİR, çok güçlü bir bazdır. (III yanlış). (C)."
