        "solution": "A, B ve D seçeneklerinde (OH bulunduran) normal bazlar var, asitle birleştiklerinde $H_2O$ (Su) çıkarırlar.\nE seçeneği Metal Oksit + Asit tepkimesidir, yine Tuz ve Su oluşur.\nAncak C seçeneğindeki $NH_3$ (Amonyak) SUSUZ bir bazdır. Yapısında Oksijen (O) yoktur. $HCl$ ile birleştiğinde sadece katı tuz ($NH_4Cl$) oluşur, SU OLUŞMAZ. (C)."
