        "question": "Aşağıda verilen pH değerlerindeki çözeltilerin eşit hacimleri karıştırıldığında hangisinde son çözeltinin pH değeri kesinlikle 7 **olmaz?**\n(Asit ve bazların eşit tesir değerliğine sahip kuvvetli asit-bazlar olduğu varsayılacaktır).",
