        "question": "Fabrika bacalarından ve araç egzozlarından havaya salınan bazı gazlar, bulutlardaki su buharıyla tepkimeye girerek asit yağmurlarını oluşturur.\nAşağıda verilen gaz - asit eşleştirmelerinden hangisi asit yağmuru oluşum sürecinde **yanlıştır?**",
