        "question": "Asit yağmurlarının çevresel ve tarihi mirasa etkileriyle ilgili;\nI. Mermerden yapılmış tarihi heykellerin ve binaların aşınmasına (Kalsiyum karbonatın çözünmesine) neden olur.\nII. Topraktaki alüminyum ($Al^{3+}$) gibi ağır metal iyonlarının çözünmesini sağlayarak suya karışmasına ve balıkları zehirlenmesine yol açar.\nIII. Tarım topraklarının pH'ını aşırı artırarak (bazikleştirerek) bitki örtüsünü kurutur.\nyargılarından hangileri doğrudur?",
