        "question": "Katı hâlde elektriği iletmeyen bir X tuzu, suya atıldığında tamamen çözünerek iletken bir çözelti oluşturuyor.\nBu çözeltiye kırmızı turnusol kâğıdı batırıldığında turnusolün rengi MAVİYE dönüyor.\nBuna göre X tuzu ile ilgili;\nI. Hidroliz olduğunda (suyla etkileştiğinde) ortama fazladan $OH^-$ iyonu sağlar.\nII. Kuvvetli bir asit ile kuvvetli bir bazın tepkimesinden (Örn: $NaCl$) oluşmuştur.\nIII. Oda koşullarında çözeltisinin pH değeri 7'den küçüktür.\nyargılarından hangileri doğrudur?",
