        "question": "Gıda mühendisi olan Elif, bir meyve suyunun analizini yapmaktadır. Meyve suyu örneğinin içine bir damla fenolftalein indikatörü damlatıldığında çözelti **renksiz** kalıyor. Daha sonra metil oranj damlatıldığında ise çözeltinin rengi **kırmızı** oluyor. (Renk tablosu Soru 5'te verilmiştir).\nBuna göre Elif'in analiz ettiği meyve suyunun pH'ı ve kimyasal karakteri hakkında ne söylenebilir?",
