        "solution": "pH'ın \"TAM 7\" olması için $H^+$ molü ile $OH^-$ molü eşit olmalı ve Kuvvetli Asit/Kuvvetli Baz olmalıdır.\nKapta: $HNO_3$ (Kuvvetli Asit). $H^+$ molü = 1 M $\\times$ 0.1 L = 0.1 mol $H^+$.\nBize 0.1 mol $OH^-$ sağlayacak KUVVETLİ bir BAZ lazım.\nA) 1 M $\\times$ 0.1 L $KOH$ = 0.1 mol $OH^-$ sağlar. KOH kuvvetlidir $\\rightarrow$ pH tam 7 olur (Doğru cevap A).\nB) Amonyak ($NH_3$) Zayıf bazdır, pH 7 olmaz.\nD) 2 M $\\times$ 0.05 L $Ba(OH)_2$ = 0.2 mol OH- verir, baz artar. (A)."
